import {HeadJson} from 'shared';
import {DocRaw} from '../../types/doc-raw';
import {DocumentError} from '../../errors/document-error';
import {validatePosOpopobSumWithHeadOhtgpb} from './validate-pos-opopob-sum-with-head-ohtgpb';

// generated by claude, adapted

// mock head raw, only lineNr and type are read
const headRaw = {lineNr: 1, type: 'HEAD'} as DocRaw;
// mock head json, only OHTGPB and the OPOPOB of the positions are needed. OHTGPB = sum of all OPOPOBs
const headJson = (ohtgpb: string, ...opopobs: string[]): HeadJson =>
    ({OHTGPB: ohtgpb, POS: opopobs.map((OPOPOB) => ({OPOPOB}))}) as HeadJson;

describe('validatePosOpopobSumWithHeadOhtgpb', () => {
    it('accepts a matching sum of two positions', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('15,50', '10,00', '5,50'))).not.toThrow();
    });

    it('accepts a single position', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('56,58', '56,58'))).not.toThrow();
    });

    it('accepts float noise (0,10 + 0,20 = 0,30)', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('0,30', '0,10', '0,20'))).not.toThrow();
    });

    it('accepts float noise with cents (0,11 + 0,21 = 0,32)', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('0,32', '0,11', '0,21'))).not.toThrow();
    });

    it('handles negative amounts with the minus on the right', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('8,00', '10,00', '2,00-'))).not.toThrow();
    });

    it('handles negative cent amounts with the minus on the right', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('8,01', '10,00', '1,99-'))).not.toThrow();
    });

    it('rejects a sum that is one cent bigger', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('15,51', '10,00', '5,50'))).toThrow(DocumentError);
    });

    it('rejects a sum that is one cent lower', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('15,49', '10,00', '5,50'))).toThrow(DocumentError);
    });

    it('reports the head line and the expected sum', () => {
        expect(() => validatePosOpopobSumWithHeadOhtgpb(headRaw, headJson('99,00', '10,00', '5,50')))
            .toThrow('Zeile 1 (HEAD): OHTGPB: Summe der Positionsbeträge stimmt nicht. Erwartet 15.50');
    });
});